def check_age(age):
    if age >= 18:
        return "adult"
    else:
        return "minor"

print(check_age(21))
print(check_age(12))

def is_positive(n):
    if n > 0:
        return True
    else:
        return False

result = is_positive(5)
print(result)
result = is_positive(-3)
print(result)

def bigger(a, b):
    if a > b:
        return a
    else:
        return b

print(bigger(10, 20))

def is_even(n):
    return n % 2 == 0

for i in range(1, 5):
    if is_even(i):
        print(i)
